using Umbraco.Bench.Umbraco.Models;
using Umbraco.Bench.Umbraco.Models.Blog;
using Umbraco.Cms.Core.Models.PublishedContent;
using Umbraco.Extensions;

namespace Umbraco.Bench.Umbraco.Services;

public class BlogPostService
{
    /// <summary>
    /// The posts beneath the blog front page that <paramref name="currentPage"/> belongs to, newest first.
    /// </summary>
    public IReadOnlyList<BlogPostSummaryModel> GetLatestPosts(IPublishedContent currentPage, int maxItems)
    {
        var frontPage = currentPage.AncestorOrSelf<BlogFrontPage>();
        if (frontPage is null)
        {
            return [];
        }

        IEnumerable<BlogPost> posts = frontPage.Children<BlogPost>()?.OrderByDescending(post => post.PublishDate) ?? [];
        if (maxItems > 0)
        {
            posts = posts.Take(maxItems);
        }

        return posts.Select(post => new BlogPostSummaryModel
        {
            Title = post.Name,
            Url = post.Url(),
            Teaser = post.Teaser,
            PublishDate = post.PublishDate,
            ImageUrl = post.MainImage?.GetCropUrl(width: 800, height: 450),
        }).ToList();
    }
}
